package org.sonatype.nexus.repository.openformats.terraform;
@org.springframework.stereotype.Component @org.springframework.context.annotation.Scope("prototype") @org.springframework.beans.factory.annotation.Qualifier("terraform") public class TerraformContent extends org.sonatype.nexus.repository.openformats.OpenContentFacet { public TerraformContent(@org.springframework.beans.factory.annotation.Qualifier("terraform") org.sonatype.nexus.repository.content.store.FormatStoreManager store) { super(store); } @Override protected String determineContentType(org.sonatype.nexus.repository.content.Asset asset,org.sonatype.nexus.blobstore.api.Blob blob,boolean strict) { if(asset.path().startsWith("/_remote/")&&"application/pgp-signature".equals(blob.getHeaders().get(org.sonatype.nexus.blobstore.api.BlobStore.CONTENT_TYPE_HEADER)))return "application/pgp-signature";return super.determineContentType(asset,blob,strict); } }
